// ---- landscape (1200 x 630) -----------------------------------------------------------
// No mascot: the slot is not drawn in landscape (LinkedIn and Google Business Profile are
// business channels and the frame is short).

const lsPhotoSplit: TemplateDef = {
  id: 'ls-photo-split',
  name: 'Photo left, text right',
  format: 'landscape',
  needsPhoto: true,
  photoFrame: { x: 0, y: 0, w: 560, h: 630 },
  probe: { x: 600, y: 615 }, // on the colour panel in both the left-to-right and mirrored layout
  logoSlot: LS_LOGO,
  build(c) {
    // Right-to-left posts mirror the layout: photo on the right, text on the left.
    const photoX = c.rtl ? 640 : 0;
    const panelX = c.rtl ? 0 : 560;
    let s = c.photo({ x: photoX, y: 0, w: 560, h: 630 });
    s += c.rect({ x: panelX, y: 0, w: 640, h: 630 }, c.P);
    s += c.rect({ x: c.rtl ? 630 : 560, y: 0, w: 10, h: 630 }, c.A);
    s += c.stack(
      { x: c.rtl ? 50 : 610, y: 160, w: 540, h: 420 },
      { align: 'left', valign: 'center', gap: 16, ink: pickInk(c.P), underBg: c.P, headline: LS_SIZES.headline(200, 3), subline: LS_SIZES.subline(80), cta: LS_SIZES.cta(96) },
    );
    s += c.logo(LS_LOGO);
    return s;
  },
};

